import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"セルフホスト概要","description":"","frontmatter":{},"headers":[],"relativePath":"ja/self-hosted/index.md","filePath":"ja/self-hosted/index.md","lastUpdated":1792323081000}'),d={name:"ja/self-hosted/index.md"};function s(l,e,h,p,i,n){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="セルフホスト概要" tabindex="-1">セルフホスト概要 <a class="header-anchor" href="#セルフホスト概要" aria-label="Permalink to &quot;セルフホスト概要&quot;">​</a></h1><p>Memoh はサーバーとして動き、ウェブクライアントも Desktop もそのクライアントです。まずサーバーの形態を決め、それからアクセス方法を選びます。</p><table tabindex="0"><thead><tr><th>場面</th><th>選択</th><th>理由</th></tr></thead><tbody><tr><td>何もインストールせず、まず試したい</td><td><a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a></td><td>ホスティングサービス。機能は同一で、サーバー運用が不要。</td></tr><tr><td>共有サーバー、リモートアクセス、本番の常時稼働、Telegram/Discord/Feishu/WeChat/メールなどのチャネル連携、マルチユーザー／マルチテナント</td><td><a href="./docker.html">Server Deploy</a></td><td>Docker Compose スタックがバックエンド、ウェブクライアント、PostgreSQL（pgvector のメモリストレージ込み）、ワークスペースランタイムを動かし続ける。</td></tr><tr><td>自分の PC でネイティブアプリを使いたい、またはこの PC を Bot が使える「コンピューター」として共有したい</td><td><a href="./desktop.html">Desktop</a></td><td>Cloud またはセルフホストサーバーに接続するネイティブクライアント。ローカルでサーバーは動かさない。</td></tr></tbody></table><h2 id="server-deploy" tabindex="-1">Server Deploy <a class="header-anchor" href="#server-deploy" aria-label="Permalink to &quot;Server Deploy&quot;">​</a></h2><p>Server Deploy は、複数人・リモート・常時稼働・マルチテナントの場面に向いています。Bot を Telegram、Discord、Feishu、WeChat、公式アカウント、メールなどの外部チャネルへ常時つないでおくなら、この形態を選んでください。</p><p>最短の道は<a href="./../guides/quick-start.html">クイックスタート</a>、完全なリファレンスは <a href="./docker.html">Server Deploy</a> にあります。</p><h2 id="desktop" tabindex="-1">Desktop <a class="header-anchor" href="#desktop" aria-label="Permalink to &quot;Desktop&quot;">​</a></h2><p>Desktop は、トレイアイコンとショートカット付きのネイティブ体験がほしい場合や、サーバー側の Bot にこの PC のファイル・シェル・ブラウザを使わせたい場合に向いています。Desktop は常にサーバー（Cloud またはセルフホスト）に接続します。詳しくは <a href="./desktop.html">Desktop</a> を参照してください。</p><h2 id="関連ページ" tabindex="-1">関連ページ <a class="header-anchor" href="#関連ページ" aria-label="Permalink to &quot;関連ページ&quot;">​</a></h2><ul><li><a href="./workspace-backends.html">Workspace バックエンド</a> が Docker・containerd・Apple・ローカルワークスペースの違いを説明しています。</li></ul>',10)])])}const m=t(d,[["render",s]]);export{k as __pageData,m as default};
